277	
278	    /**
279	     * Return the Pet with the given name, or null if none found for this Owner.
280	     *
281	     * @param name to test
282	     * @return true if pet name is already in use
283	     */
284	    public Pet getPet(String name, boolean ignoreNew) {
285	        name = name.toLowerCase();
286	        for (Pet pet : getPetsInternal()) {
287	            if (!ignoreNew || !pet.isNew()) {
288	                String compName = pet.getName();
289	                compName = compName.toLowerCase();
290	                if (compName.equals(name)) {
291	                    return pet;
292	                }
293	            }
294	        }
295	        return null;
296	    }
297	
298	    public Pet getPet(Integer petId) {
